function transform (message, context) {
  // -------------------------------------------------------------
  // DATE FUNCTIONS FOR PIPELINES

  // Returns a JavaScript date as of a given offset
  // Use negative numbers to get past dates
  const getOffsetDate = (offset) => {
    const newDate = new Date();
    // Calc the Offset
    newDate.setDate(newDate.getDate() + offset);
    return newDate;
  };

  // Formats a JavaScript Date in YYYY-MM-DD format
  // Ethos APIs typically return dates in this format
  const formatDateAsAPI = (date) => {
    return date.toISOString().split('T')[0];
  };

  // Returns an Oracle DB formatted Date
  // This converts a date formatted 'YYYY-MM-DD' (or a JS Date) to Oracle Date 'DD-MON-YYYY'
  const formatDateAsOracle = (date) => {
    const myDate = typeof date === 'string' ? date : formatDateAsAPI(date);
    const months = ['SKIP', 'JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];
    const [y, m, d] = myDate.split('-');
    return [d, months[parseInt(m)], y].join('-');
  };
  // -------------------------------------------------------------

  // get Params
  const { startsOnOrBeforeDate , endsOnOrAfterDate , calculationDate } = context;

  // Default Value if parameters not provided
  const today = formatDateAsAPI( new Date() );
  const nextYear = formatDateAsAPI( getOffsetDate( 365 ) );
  const lastYear = formatDateAsAPI( getOffsetDate( -365 ) );

  message.payload.startsOnOrBeforeDate = startsOnOrBeforeDate || nextYear;  // Used to get terms from term-codes
  message.payload.endsOnOrAfterDate = endsOnOrAfterDate || lastYear;        // Used to get terms from term-codes
  message.payload.calculationDate = calculationDate || today;               // Used to calculate future terms in final transform 

  return message;
}

function transform (message, context) {
  // -------------------------------------------------------------
  // Converts a full JS date string to just the YYYY-MM-DD format

  const dateOnly = ( dateTime ) => {
    return dateTime?.substring( 0 , 10 );
  }

  // -------------------------------------------------------------

  const calculationDate = message.payload.calculationDate;
  const semesterTermType = 'S';

  // By default terms are sorted by start date desc and end date desc, so we don't need to do futher sorting.

  // Get API response filtered by Term Type
  const terms = message.payload?.terms?.filter( (term) => term?.trmtCode ) || [];
  message.payload.terms = terms;

  // Create the different groupings of terms
  message.payload.currentTerms = terms.filter( ( term ) => dateOnly(term?.startDate) <= calculationDate && dateOnly( term?.endDate ) >= calculationDate );
  message.payload.futureTerms = terms.filter( ( term ) => dateOnly( term?.startDate )> calculationDate );
  message.payload.pastTerms = terms.filter( ( term ) => dateOnly( term?.endDate ) < calculationDate );
  message.payload.currentSemesters = message.payload.currentTerms.filter( ( term ) => term?.trmtCode === 'S' );
  message.payload.futureSemesters = message.payload.futureTerms.filter( ( term ) => term?.trmtCode === 'S' );
  message.payload.pastSemesters = message.payload.pastTerms.filter( ( term ) => term?.trmtCode === 'S' );

  // Calculate individual terms
  message.payload.currentTerm = message.payload.currentTerms?.[0];
  message.payload.currentSemester = message.payload.currentSemesters?.[0];
  message.payload.nextTerm = message.payload.futureTerms?.[ message.payload.futureTerms?.length - 1 ]; // Since the are by desc, grab the last to be equivalent to asc
  message.payload.lastTerm = message.payload.pastTerms?.[0];
  message.payload.nextSemester = message.payload.futureSemesters?.[ message.payload.futureSemesters?.length - 1]; // Since the are by desc, grab the last to be equivalent to asc
  message.payload.lastSemester = message.payload.pastSemesters?.[0];

  return message;
}
